import numpy as onp

import jax.numpy as np
from jax import random, jit, grad, vmap, lax, remat
from functools import partial


#######################################
#Error only when all of these are True#
#######################################
function_test = True
test_remat = True
test_scan = True


def pot(dr, D0=5.0, **kwargs):
  U = dr**2
  if(function_test):
    U = D0 * U
  else:
    U = U - D0
  return np.array(U, dtype=dr.dtype)

def sys_energy(metric, D0=5.0):
  def fn_mapped(R, **dynamic_kwargs):
    _metric = vmap(vmap(partial(metric, **dynamic_kwargs), (0, None), 0), (None, 0), 0)
    dr = _metric(R, R)
    return np.sum(
        pot(dr, D0=D0),
        axis=None,
        keepdims=False)
  return fn_mapped

def create_simulation(params):
  D0 = params
  def displacement(Ra, Rb, **unused_kwargs):
    return Ra - Rb
  def shift(R, dR, **unused_kwargs):
    return R + 0.001*dR

  energy_fn = sys_energy(displacement, D0=D0)

  def get_dynamics_functions(energy_fn, shift):
    force_fn = grad(lambda R, *args, **kwargs: -energy_fn(R, *args, **kwargs))
    def init_fn(R):
      return R
    def apply_fn(state, **kwargs):
      R = state
      F = force_fn(R, **kwargs)
      R = shift(R, F)
      return R
    return init_fn, apply_fn

  return get_dynamics_functions(energy_fn, shift)

def run(params):
  key2, split = random.split(key,2)
  init_fn, apply_fn = create_simulation(params)

  R = random.uniform(
    split, (N, dimension), minval=0.0, maxval=8.0, dtype=np.float32)

  state = init_fn(R)

  n_steps_inner = 3
  n_steps_outer = 2

  def run_partial(state, i):
    def loop_fn(s, i):
      return apply_fn(s), np.array([0.])
    if(test_scan):
      steps = np.arange(0,n_steps_inner)
      return lax.scan(loop_fn, state, steps)
    else:
      return loop_fn(loop_fn(loop_fn(state,0)[0],0)[0],0)


  if(test_remat):
    run_partial = remat(run_partial)

  run_partial = jit(run_partial)

  #Surprisingly, this scan doesn't seem to affect things one way or another...
  state, temp = lax.scan(run_partial, state, np.arange(n_steps_outer))
  #state, temp = run_partial(run_partial(state,0)[0],0)


  return np.mean(state)


key = random.PRNGKey(0)
N = 10
dimension = 3

grad(run)(20.0)

Here's the recommendation, which JAX uses internally (from
#1925 (comment)):

The standard way to handle keyword arguments or unusual function signatures with jit is to write a helper function, e.g.,
@functools.partial(jax.jit, static_argnums=(1,))
def _my_func(x, y):
  ...

def my_func(x, y):
  return _my_func(x, y)
Now you can write something like my_func(x=1, y=2) and y will still be a static argument.

