The tree_flatten function currently returns a list of arrays, and this is indeed very useful to have in many cases.
Sometimes, it might be also useful to further flatten the already flattened list to a single contiguous 1d array, and then have the option to zip it up to a list of arrays again. This can be done with a trivial wrapper, but it might be useful to add an optional argument to tree_flatten which does this for convenience.
Here's a class which builds on tree_util to do this, assuming all leaves of the pytree [I mean the data stored in the tree] have the attributes .shape and .size.
import numpy as np
import jax.numpy as jnp
from jax import jit
from jax.tree_util import tree_structure, tree_flatten, tree_unflatten

class NN_Tree(object):

    def __init__(self,pytree):
        # assumes flattened elements are all arrays

        flattened, self.tree = tree_flatten(pytree)

        self.shapes=[]
        self.sizes=np.zeros(len(flattened),dtype=int)

        for j,x in enumerate(flattened):

            self.shapes.append(x.shape)
            self.sizes[j]=x.size

    @jit
    def flatten(self,data):
        # flatten maximally
        return jnp.concatenate([x.flatten() for x in self.tree.flatten_up_to(data)])

    @jit
    def unflatten(self,data):
        # restore shapes
        cum_size=0
        data_flattened=[]
        for j,size in enumerate(self.sizes):
            data_flattened.append( jnp.array(data[cum_size:cum_size+size].reshape(self.shapes[j])) )
            cum_size+=size

        # unflatten
        return self.tree.unflatten(data_flattened)

Dear jax team,
I am implementing numpy.gradient in jax and, while my code numerically works, I am struggling with handling static_argnums where the static argument is a keyword argument.
The original function signature is numpy.gradient(f, *varargs, **kwargs) where *varargs are spacings and **kwargs may be edge_order or axis. I implemented only support for axis, but my question is valid for a complete implementation, too.

How can I follow numpy's signature while telling jax the static argument?
Is following the signature strictly necessary when contributing to jax?

My implementation which works for me but does not follow the original signature:
import jax
import jax.numpy as np
import numpy as onp


@jax.partial(jax.jit, static_argnums=1)
def gradient(a, axis=None):

  def _gradient_along_axis(a, axis):
    a_swap = np.swapaxes(a, 0, axis)
    a_grad = np.concatenate((
      (a_swap[1]  - a_swap[0])[np.newaxis],
      (a_swap[2:] - a_swap[:-2]) * 0.5,
      (a_swap[-1] - a_swap[-2])[np.newaxis]
      ), axis=0)
    return np.swapaxes(a_grad, 0, axis)

  if axis is None:
    axis = range(a.ndim)
  else:
    if isinstance(axis, int):
      axis = (axis,)
    if not isinstance(axis, tuple):
      raise ValueError("Give `axis` either as int or tuple of ints")

  a_grad = [_gradient_along_axis(a, ax) for ax in axis]

  if len(axis) == 1:
    a_grad = a_grad[0]

  return a_grad


# TEST
key = jax.random.PRNGKey(0)
x = jax.random.normal(key, (10, 20, 30))

for axis in [None, 0, 1, 2, -0, -1, -2, (0, 1), (0, 1, 2), (-1, -2), (-2, -1), (-1, 0)]:
  print(axis)
  assert np.allclose(
    gradient(x, axis),
    onp.gradient(x, axis=axis),
    rtol=1e-6, atol=1e-6
  )

import numpy as np
from functools import partial
import jax.numpy as jnp
from jax import jit, random
from collections import namedtuple
from multiprocessing import Process, Queue
from pickle import dumps


class Brain(namedtuple("Brain", ("w1", "b1", "w2", "b2"))):
    def __sub__(self, other):
        return Brain(
            w1=self.w1 - other.w1,
            b1=self.b1 - other.b1,
            w2=self.w2 - other.w2,
            b2=self.b2 - other.b2,
        )

    def __mul__(self, scalar):
        return Brain(
            w1=self.w1 * scalar,
            b1=self.b1 * scalar,
            w2=self.w2 * scalar,
            b2=self.b2 * scalar,
        )

    __rmul__ = __mul__


def get_brain(
    input_size: int, hidden_size: int, output_size: int, max_memory: int, seed: int
):
    key = random.PRNGKey(seed)
    w1 = random.truncated_normal(
        key, lower=0, upper=0.1, shape=(input_size, hidden_size)
    )
    w2 = random.truncated_normal(
        key, lower=0, upper=0.1, shape=(hidden_size, output_size)
    )
    b1 = jnp.zeros(shape=(hidden_size,))
    b2 = jnp.zeros(shape=(output_size,))
    return Brain(w1=w1, b1=b1, w2=w2, b2=b2)


@jit
def forward(brain: Brain, data: np.ndarray):
    o1 = jnp.matmul(data, brain.w1) + brain.b1
    a1 = jnp.tanh(o1)
    o2 = jnp.matmul(a1, brain.w2) + brain.b2
    a2 = o2 - jnp.expand_dims(jnp.log(jnp.exp(o2).sum(axis=1)), 1)
    return a2


def worker(queue):
    import jax.numpy as jnp
    from jax import grad, jit

    @jit
    def forward(brain: Brain, data: np.ndarray):
        o1 = jnp.matmul(data, brain.w1) + brain.b1
        a1 = jnp.tanh(o1)
        o2 = jnp.matmul(a1, brain.w2) + brain.b2
        a2 = o2 - jnp.expand_dims(jnp.log(jnp.exp(o2).sum(axis=1)), 1)
        return a2

    @jit
    def loss(brain: Brain, data: np.ndarray, labels: np.ndarray):
        pred = forward(brain, data)
        loss = jnp.mean(-(labels * pred).sum(1))
        return loss

    @jit
    def grad_loss(brain: Brain, data: np.ndarray, labels: np.ndarray):
        return partial(grad(loss), data=data, labels=labels)(brain)

    @jit
    def sgd(brain: Brain, data: np.ndarray, labels: np.ndarray, learning_rate: float):
        g = grad_loss(brain, data, labels)
        brain = brain - g * learning_rate
        return brain

    while True:
        brain, data, label, epoch, learning_rate = queue.get()
        for i in range(epoch):
            brain = sgd(brain, data, labels, learning_rate)
        break # if multiprocess the control flow dows not even come here, nothing get's returned from forward


if __name__ == "__main__":
    brain = get_brain(100, 200, 9, 1000, 1)
    data = np.random.normal(size=(1000, 100))
    labels = np.random.uniform(0, 1, size=(1000, 9))
    queue = Queue(10)
    workers = []
    for i in range(2):
        p = Process(target=worker, args=(queue,))
        p.start()  # does not work
        workers.append(p)
    for i in range(10):
        queue.put((brain, data, labels, 1000, 1))
    worker(queue)  # works
